import type { Zone } from '@/lib/domain/types';
import { useSettings } from '@/lib/store/settings-store';
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import * as Haptics from 'expo-haptics';
import { Platform } from 'react-native';

/**
 * Sound effects and the small haptic tap that goes with them. Spooky 8-bit, to match the pixel-art UI,
 * generated by scripts/make-pixel-sounds.mjs: a cold breath and a wobbling diminished arpeggio for the fridge,
 * an icy hiss and a music-box tritone for the freezer, a long creak and a moan for the pantry, a shovel and a
 * tolling bell for burying, a wavering wail for a ghost, all with an echo tail.
 * Everything here is best effort:
 * no audio device, autoplay rules or a missing vibration motor must never break opening a door.
 */

type Action = 'open' | 'close';

type Sfx = 'bury' | 'ghost' | 'rescue' | 'spoil';

const SOURCES: Record<string, number> = {
  'fridge-open': require('@/assets/sounds/chip-fridge-open.wav'),
  'fridge-close': require('@/assets/sounds/chip-fridge-close.wav'),
  'freezer-open': require('@/assets/sounds/chip-freezer-open.wav'),
  'freezer-close': require('@/assets/sounds/chip-freezer-close.wav'),
  'pantry-open': require('@/assets/sounds/chip-pantry-open.wav'),
  'pantry-close': require('@/assets/sounds/chip-pantry-close.wav'),
  bury: require('@/assets/sounds/chip-bury.wav'),
  ghost: require('@/assets/sounds/chip-ghost.wav'),
  rescue: require('@/assets/sounds/chip-rescue.wav'),
  spoil: require('@/assets/sounds/chip-spoil.wav'),
};

/** Quiet: UI sounds should sit under whatever the user is listening to, not over it. */
const VOLUME = 0.55;

const players = new Map<string, AudioPlayer>();
let modeSet = false;

function player(key: string): AudioPlayer {
  let p = players.get(key);
  if (!p) {
    if (!modeSet) {
      modeSet = true;
      // Mix with the user's music instead of pausing it, and stay silent when the phone is on silent.
      void setAudioModeAsync({ interruptionMode: 'mixWithOthers', playsInSilentMode: false }).catch(() => {});
    }
    p = createAudioPlayer(SOURCES[key]);
    p.volume = VOLUME;
    players.set(key, p);
  }
  return p;
}

/** Plays the door's sound and a light tap. Does nothing when "Sounds and vibration" is off. */
export function doorFeedback(zone: Zone, action: Action) {
  if (!useSettings.getState().settings.soundEffects) return;
  play(`${zone}-${action}`);
  // Opening is a light tap, shutting a slightly firmer one, like the real thing.
  void Haptics.impactAsync(action === 'open' ? Haptics.ImpactFeedbackStyle.Light : Haptics.ImpactFeedbackStyle.Medium).catch(() => {});
}

/** A one-off sound with a tap: burying, poking a ghost, rescuing food, or food spoiling. Off with "Sounds and vibration". */
export function sfx(name: Sfx) {
  if (!useSettings.getState().settings.soundEffects) return;
  play(name);
  if (name === 'rescue') { void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => {}); return; }
  void Haptics.impactAsync(name === 'bury' || name === 'spoil' ? Haptics.ImpactFeedbackStyle.Heavy : Haptics.ImpactFeedbackStyle.Light).catch(() => {});
}

function play(key: string) {
  if (Platform.OS === 'web') return playOnWeb(key);
  try {
    const p = player(key);
    void p.seekTo(0).catch(() => {});
    p.play();
  } catch {
    // No audio available. Whatever triggered it still happens.
  }
}

/**
 * Web: a plain <audio> element, because expo-audio's web player calls play() without handling a refusal
 * (autoplay rules, or a browser with no decoder), which surfaces as an unhandled error.
 */
const webAudio = new Map<string, HTMLAudioElement>();
function playOnWeb(key: string) {
  try {
    let a = webAudio.get(key);
    if (!a) {
      const src = SOURCES[key] as unknown as { uri?: string } | string;
      const uri = typeof src === 'string' ? src : src?.uri;
      if (!uri || typeof Audio === 'undefined') return;
      a = new Audio(uri);
      a.volume = VOLUME;
      webAudio.set(key, a);
    }
    a.currentTime = 0;
    void a.play().catch(() => {});
  } catch {
    // No audio available.
  }
}
